const {spawnSync}=require('child_process');
const B='/workspace/dataset/test4_executable';
function out(v){const r=spawnSync(B,['--a',v],{encoding:'buffer'});return {h:r.stdout.toString('hex'),c:r.status,e:r.stderr.toString('utf8').trim()};}
// doubled probe: 'a'+C+C+'b'  -> sep gives 615f62, non-sep gives 61 CC CC 62
const seps=[],nonseps=[],weird=[];
for(let c=1;c<128;c++){
  const ch=String.fromCharCode(c);
  const v='a'+ch+ch+'b';
  const r=out(v);
  const expNon=Buffer.from(v.toLowerCase(),'utf8').toString('hex')+'0a';
  if(r.h==='615f620a') seps.push(c);
  else if(r.h===expNon) nonseps.push(c);
  else weird.push([c,r.h,r.c,r.e]);
}
console.log('SEPS n='+seps.length, seps.map(x=>x.toString(16).padStart(2,'0')).join(' '));
console.log('NONSEPS n='+nonseps.length, nonseps.map(x=>x.toString(16).padStart(2,'0')).join(' '));
console.log('WEIRD', JSON.stringify(weird));
EOF
